// Standard initialization (equivalent to inotify_init1(0))
int fd = inotify_init();
// fd is the inotify file descriptor

// Use fd for operations like inotify_add_watch()
if (fd == -1) {
    // Handle error (e.g., EMFILE, ENOMEM)
}

// Initialization with behavior flags (Linux specific)
int fd1 = inotify_init1(IN_CLOEXEC | IN_NONBLOCK);

if (fd1 == -1) {
    // Check for EINVAL if flags are unsupported
}

// Cleanup
if (fd >= 0) { close(fd); }
